// RetryingPaymentGateway.charge
let timedOut = false;
for (let attempt = 1; ; attempt++) {
  try {
    return await this.#inner.charge(req);
  } catch (e) {
    if (e instanceof PaymentTimeoutError) timedOut = true;
    if (!isTransient(e) || attempt >= this.#maxAttempts) {
      // 1 回でも時間切れがあれば、課金済みかもしれない
      if (timedOut && isTransient(e)) throw new PaymentTimeoutError({ cause: e });
      throw e;
    }
    // ...待つ
  }
}

// OrderService.checkout の catch
if (e instanceof PaymentDeclinedError || e instanceof PaymentUnavailableError) {
  order.status = 'PAYMENT_FAILED'; // 課金されていないと分かっている
  await this.#orders.save(order);
}
// それ以外は PENDING_PAYMENT のまま照合バッチへ
throw e;
